pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero-attempt configuration cannot make a call; honor the documented
    // minimum without introducing a new public error variant.
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() => return Err(error),
            Err(error) if attempts >= max_attempts => return Err(error),
            Err(_) => {
                let retry_number = attempts;
                sleeper.sleep_ms(config.delay_for_retry(retry_number));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig::new(max_attempts, base_delay_ms, max_delay_ms)
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let calls = Cell::new(0);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls.set(calls.get() + 1);
            if calls.get() < 3 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls.get(), 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let calls = Cell::new(0);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls.set(calls.get() + 1);
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls.get(), 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let calls = Cell::new(0);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(3, 1, 100), &mut sleeper, || {
            calls.set(calls.get() + 1);
            Err(RetryError::Transient("down".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("down".into())));
        assert_eq!(calls.get(), 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }
}

