use jobrunner::{run_job, RetryConfig, RetryError, FakeSleeper};

#[test]
fn public_api_retries_transient_failures_with_a_bounded_schedule() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(
        &RetryConfig::new(5, 10, 25),
        &mut sleeper,
        || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("service unavailable".into()))
            } else {
                Ok(())
            }
        },
    );

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(
        &RetryConfig::new(5, 10, 25),
        &mut sleeper,
        || {
            calls += 1;
            Err(RetryError::Permanent("invalid job".into()))
        },
    );

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

